const $=(s)=>document.querySelector(s);const $$=(s)=>[...document.querySelectorAll(s)];
document.body.classList.add('js-ready');
const reduced=matchMedia('(prefers-reduced-motion: reduce)');let paused=reduced.matches;
function setMotion(value){paused=value;document.body.classList.toggle('motion-off',paused);$('.motion').setAttribute('aria-pressed',String(paused));$('.motion').setAttribute('aria-label',paused?'Activar movimiento':'Pausar movimiento');$('.motion-icon').textContent=paused?'▷':'Ⅱ';window.dispatchEvent(new CustomEvent('nodo-motion',{detail:{paused}}));}
setMotion(paused);$('.motion').addEventListener('click',()=>setMotion(!paused));reduced.addEventListener('change',e=>setMotion(e.matches));
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');observer.unobserve(e.target);}}),{threshold:.12});$$('.reveal').forEach(el=>observer.observe(el));
const wordHeading=$('.word-reveal');const walker=document.createTreeWalker(wordHeading,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(node=>{const frag=document.createDocumentFragment();node.textContent.split(/(\s+)/).forEach(word=>{if(!word.trim()){frag.append(word);return}const span=document.createElement('span');span.className='word';span.textContent=word;frag.append(span)});node.replaceWith(frag)});
const words=$$('.word');let scrollQueued=false;
function updateScroll(){scrollQueued=false;const max=document.documentElement.scrollHeight-innerHeight;$('.reading-progress').style.width=`${max?scrollY/max*100:0}%`;const bounds=wordHeading.getBoundingClientRect();const t=Math.max(0,Math.min(1,(innerHeight*.9-bounds.top)/(innerHeight*.7)));words.forEach((word,i)=>word.classList.toggle('lit',paused||t>(i/words.length)));const p=$('.process').getBoundingClientRect();$('.process-track i').style.width=`${Math.max(0,Math.min(1,(innerHeight-p.top)/(p.height)))*100}%`;if(!paused){const e=$('.encounter').getBoundingClientRect();$('.encounter>img').style.transform=`translateY(${Math.max(-80,Math.min(80,e.top*.12))}px)`;}}
addEventListener('scroll',()=>{if(!scrollQueued){scrollQueued=true;requestAnimationFrame(updateScroll)}},{passive:true});addEventListener('resize',updateScroll);updateScroll();
$('.menu').addEventListener('click',()=>{const open=$('.header').classList.toggle('menu-open');$('.menu').setAttribute('aria-expanded',String(open));$('.menu').setAttribute('aria-label',open?'Cerrar menú':'Abrir menú');$('.menu').textContent=open?'×':'☰'});$$('header nav a').forEach(a=>a.addEventListener('click',()=>{$('.header').classList.remove('menu-open');$('.menu').setAttribute('aria-expanded','false');$('.menu').textContent='☰'}));
$$('.service').forEach(item=>item.addEventListener('toggle',()=>{if(item.open)$$('.service').forEach(other=>{if(other!==item)other.open=false})}));
const tabs=$$('.lab [role=tab]');function selectTab(tab){tabs.forEach(t=>{const active=t===tab;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1;const panel=$('#panel-'+t.dataset.panel);panel.hidden=!active;panel.classList.toggle('active',active)});}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectTab(tab));tab.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(index+1)%tabs.length;else if(e.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();selectTab(tabs[next]);tabs[next].focus();}})});
$('#demo-theme').addEventListener('click',()=>$('.browser-demo').classList.toggle('alt'));$('#demo-button').addEventListener('click',()=>{const active=$('.demo-page').classList.toggle('activated');$('#demo-result').textContent=active?'Una interacción transforma la forma de explorar una idea.':'Cada clic puede tener un propósito.';$('#demo-button').textContent=active?'Volver al inicio ↗':'Explorar la idea ↗'});
const dialog=$('#brief');function openBrief(service){$('#brief-form').hidden=false;$('#brief-result').hidden=true;$('#copy-status').textContent='';if(service)$('#service-select').value=service;dialog.showModal();}$$('.contact-open').forEach(b=>b.addEventListener('click',()=>openBrief()));$$('.service-contact').forEach(b=>b.addEventListener('click',()=>openBrief(b.dataset.service)));$('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close()});
$('#brief-form').addEventListener('submit',e=>{e.preventDefault();const idea=$('#project-idea').value.trim();if(!idea){$('#project-idea').focus();return}$('#message-output').value=`¡Hola, NODO! Me interesa ${$('#service-select').value.toLowerCase()}.\n\n${idea}\n\nMe gustaría conversar sobre el alcance y los próximos pasos.`;const whatsappUrl='https://wa.me/5493482219413?text='+encodeURIComponent($('#message-output').value);$('#whatsapp-link').href=whatsappUrl;$('#brief-form').hidden=true;$('#brief-result').hidden=false;window.open(whatsappUrl,'_blank','noopener,noreferrer');$('#whatsapp-link').focus()});
$('#copy-message').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('#message-output').value);$('#copy-status').textContent='Mensaje copiado. Ya podés pegarlo en WhatsApp.';}catch{$('#message-output').focus();$('#message-output').select();$('#copy-status').textContent='Seleccionamos el mensaje: copialo con Ctrl+C o mantené presionado para copiar.';}});
if(matchMedia('(pointer:fine)').matches){addEventListener('pointermove',e=>{if(paused)return;$('.cursor').style.opacity='.7';$('.cursor').style.left=e.clientX+'px';$('.cursor').style.top=e.clientY+'px';},{passive:true});document.addEventListener('pointerleave',()=>$('.cursor').style.opacity='0');}
